{
  "title": "Expats and job hunting in Slovakia and Austria",
  "topics": [
    {
      "id": "expat-locations",
      "title": "People living in Slovakia/Bratislava",
      "claims": [
        {
          "text": "Some participants know individuals living abroad, including one in Austria and one in Poland.",
          "evidence": [3]
        },
        {
          "text": "Participant P3 has at least two acquaintances in Austria, one recently arrived and another who has been there for several years.",
          "evidence": [12, 13]
        }
      ]
    },
    {
      "id": "job-search",
      "title": "Job search strategies",
      "claims": [
        {
          "text": "LinkedIn is recommended as the primary tool for finding jobs abroad.",
          "evidence": [18]
        },
        {
          "text": "A high volume of applications (about 100) typically yields only a few interview invitations (3).",
          "evidence": [21]
        },
        {
          "text": "Most job postings in the region require knowledge of the local language.",
          "evidence": [26]
        }
      ]
    },
    {
      "id": "language-requirements",
      "title": "Language requirements for jobs",
      "claims": [
        {
          "text": "German is the main spoken language in Austria, though English is also used.",
          "evidence": [14, 15]
        },
        {
          "text": "Employers commonly ask for a B2 level of the local language, with B1 sometimes accepted; certificates are rarely required.",
          "evidence": [46]
        },
        {
          "text": "Workplace communication can be conducted in English.",
          "evidence": [44]
        }
      ]
    },
    {
      "id": "interview-experience",
      "title": "Interview conversion and experience",
      "claims": [
        {
          "text": "Conversion from applications to interviews is low, e.g., 3 interviews from ~100 applications.",
          "evidence": [21]
        },
        {
          "text": "Candidates with 2–3 years of experience can secure interviews even without strong language skills.",
          "evidence": [23, 29]
        }
      ]
    },
    {
      "id": "salary",
      "title": "Salary expectations",
      "claims": [
        {
          "text": "Salaries in Europe are generally higher than in Ukraine, though many overlook this factor.",
          "evidence": [35]
        },
        {
          "text": "Even the minimal accepted salary was still higher than fast‑food wages.",
          "evidence": [37]
        }
      ]
    },
    {
      "id": "language-learning",
      "title": "Learning the local language",
      "claims": [
        {
          "text": "Learning the local language is important for daily life and feeling comfortable in the city.",
          "evidence": [47]
        },
        {
          "text": "Typical employer requirement is B2, but B1 may be sufficient; candidates often list B2 in resumes without certification.",
          "evidence": [46]
        }
      ]
    }
  ],
  "decisions": [
    {
      "text": "Use LinkedIn as the primary platform for searching jobs abroad.",
      "evidence": [18]
    }
  ],
  "openQuestions": [
    {
      "text": "Who currently lives in Bratislava or elsewhere in Slovakia?",
      "evidence": [1]
    },
    {
      "text": "Are you working for an Austrian company?",
      "evidence": [9]
    },
    {
      "text": "What are typical salary ranges for junior positions in this market?",
      "evidence": [34]
    }
  ]
}
